import java.util.*;

class Solution {
  public boolean isTransformable(String s, String t) {
    List<Deque<Integer>> positions = new ArrayList<>();
    for (int d = 0; d < 10; d++) positions.add(new ArrayDeque<>());
    for (int i = 0; i < s.length(); i++) positions.get(s.charAt(i) - '0').add(i);
    for (int i = 0; i < t.length(); i++) {
      int digit = t.charAt(i) - '0';
      if (positions.get(digit).isEmpty()) return false;
      int index = positions.get(digit).peek();
      for (int smaller = 0; smaller < digit; smaller++) {
        if (!positions.get(smaller).isEmpty() && positions.get(smaller).peek() < index)
          return false;
      }
      positions.get(digit).poll();
    }
    return true;
  }
}
